def count_grey_cells(R, C, K):
    def is_grey(row, col):
        return any((row & (1 << i)) == (col & (1 << i)) == 0 for i in range(64))

    def count_greys_in_segment(start_row, start_col, length, direction):
        count = 0
        row, col = start_row, start_col
        for _ in range(length):
            if is_grey(row, col):
                count += 1
            if direction == 'right':
                col += 1
            elif direction == 'down':
                row += 1
            elif direction == 'left':
                col -= 1
            elif direction == 'up':
                row -= 1
        return count

    total_grey_count = 0
    current_row, current_col = 0, 0
    direction = 'right'
    steps = 0

    while steps < K:
        segment_length = min(K - steps, C if direction in ['right', 'left'] else R)
        total_grey_count += count_greys_in_segment(current_row, current_col, segment_length, direction)
        steps += segment_length

        if direction == 'right':
            current_col += segment_length
            direction = 'down'
        elif direction == 'down':
            current_row += segment_length
            direction = 'left'
        elif direction == 'left':
            current_col -= segment_length
            direction = 'up'
        elif direction == 'up':
            current_row -= segment_length
            direction = 'right'

        # Adjust for boundaries
        if current_col >= C:
            current_col = C - 1
            direction = 'up'
        elif current_col < 0:
            current_col = 0
            direction = 'down'
        elif current_row >= R:
            current_row = R - 1
            direction = 'left'
        elif current_row < 0:
            current_row = 0
            direction = 'right'

    return total_grey_count

